import * as THREE from 'three';

/**
 * All textures are authored to be sampled with METER-BASED UVs generated by the
 * procedural roof builder (each mesh face gets UVs in real-world meters, scaled per
 * material). Every texture is seamlessly tileable.
 */
export interface ProceduralTextureSet {
  shingleColor: THREE.CanvasTexture;
  shingleNormal: THREE.CanvasTexture;
  shingleRoughness: THREE.CanvasTexture;
  underlaymentColor: THREE.CanvasTexture;
  underlaymentNormal: THREE.CanvasTexture;
  iceWaterColor: THREE.CanvasTexture;
  iceWaterNormal: THREE.CanvasTexture;
  iceWaterRoughness: THREE.CanvasTexture;
  plywoodColor: THREE.CanvasTexture;
  plywoodNormal: THREE.CanvasTexture;
  plywoodRoughness: THREE.CanvasTexture;
  plywoodEdge: THREE.CanvasTexture;
  lumberColor: THREE.CanvasTexture;
  lumberNormal: THREE.CanvasTexture;
  lumberRoughness: THREE.CanvasTexture;
  insulationColor: THREE.CanvasTexture;
  insulationNormal: THREE.CanvasTexture;
  metalColor: THREE.CanvasTexture;
  metalNormal: THREE.CanvasTexture;
  soffitColor: THREE.CanvasTexture;
  soffitNormal: THREE.CanvasTexture;
  ventColor: THREE.CanvasTexture;
  ventNormal: THREE.CanvasTexture;
  dispose: () => void;
}

/** Deterministic Mulberry32 PRNG */
export function createSeededRng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function yieldToIdle(): Promise<void> {
  return new Promise((resolve) => {
    const win = window as Window & {
      requestIdleCallback?: (cb: () => void, opts?: { timeout: number }) => void;
    };
    if (typeof win.requestIdleCallback === 'function') {
      win.requestIdleCallback(() => resolve(), { timeout: 32 });
    } else {
      setTimeout(resolve, 0);
    }
  });
}

function makeCanvas(w: number, h = w): [HTMLCanvasElement, CanvasRenderingContext2D] {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const ctx = c.getContext('2d', { willReadFrequently: true })!;
  return [c, ctx];
}

/** Tileable 2D value noise. Sample with u,v in [0,1) tile space. */
function createTileNoise(rng: () => number, period: number) {
  const grid = new Float32Array(period * period);
  for (let i = 0; i < grid.length; i++) grid[i] = rng();
  const smooth = (t: number) => t * t * (3 - 2 * t);
  return (u: number, v: number) => {
    const x = (((u % 1) + 1) % 1) * period;
    const y = (((v % 1) + 1) % 1) * period;
    const x0 = Math.floor(x);
    const y0 = Math.floor(y);
    const fx = smooth(x - x0);
    const fy = smooth(y - y0);
    const x1 = (x0 + 1) % period;
    const y1 = (y0 + 1) % period;
    const a = grid[y0 * period + x0];
    const b = grid[y0 * period + x1];
    const c = grid[y1 * period + x0];
    const d = grid[y1 * period + x1];
    return a + (b - a) * fx + (c - a) * fy + (a - b - c + d) * fx * fy;
  };
}

/** Tileable fractal noise (0..1) built from several octave noise tables */
function createFbm(rng: () => number, basePeriod: number, octaves: number) {
  const layers = Array.from({ length: octaves }, (_, o) => createTileNoise(rng, basePeriod << o));
  return (u: number, v: number) => {
    let sum = 0;
    let amp = 1;
    let norm = 0;
    for (let o = 0; o < octaves; o++) {
      sum += layers[o](u, v) * amp;
      norm += amp;
      amp *= 0.5;
    }
    return sum / norm;
  };
}

/** Converts a grayscale height buffer into a tangent-space RGB normal map canvas */
function heightToNormalCanvas(
  height: Float32Array,
  w: number,
  h: number,
  strength = 2.4
): HTMLCanvasElement {
  const [dstCanvas, dstCtx] = makeCanvas(w, h);
  const dstImg = dstCtx.createImageData(w, h);
  const dst = dstImg.data;
  const sample = (x: number, y: number) => height[((y + h) % h) * w + ((x + w) % w)];

  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let nx = (sample(x - 1, y) - sample(x + 1, y)) * strength;
      let ny = (sample(x, y + 1) - sample(x, y - 1)) * strength;
      let nz = 1.0;
      const inv = 1.0 / Math.sqrt(nx * nx + ny * ny + nz * nz);
      nx *= inv;
      ny *= inv;
      nz *= inv;
      const idx = (y * w + x) * 4;
      dst[idx] = Math.round((nx * 0.5 + 0.5) * 255);
      dst[idx + 1] = Math.round((ny * 0.5 + 0.5) * 255);
      dst[idx + 2] = Math.round((nz * 0.5 + 0.5) * 255);
      dst[idx + 3] = 255;
    }
  }
  dstCtx.putImageData(dstImg, 0, 0);
  return dstCanvas;
}

/** Reads the red channel of a canvas into a 0..1 height buffer */
function canvasToHeight(ctx: CanvasRenderingContext2D, w: number, h: number): Float32Array {
  const data = ctx.getImageData(0, 0, w, h).data;
  const out = new Float32Array(w * h);
  for (let i = 0; i < w * h; i++) out[i] = data[i * 4] / 255;
  return out;
}

function grayCanvas(values: Float32Array, w: number, h: number): HTMLCanvasElement {
  const [c, ctx] = makeCanvas(w, h);
  const img = ctx.createImageData(w, h);
  for (let i = 0; i < w * h; i++) {
    const v = Math.max(0, Math.min(255, Math.round(values[i] * 255)));
    img.data[i * 4] = img.data[i * 4 + 1] = img.data[i * 4 + 2] = v;
    img.data[i * 4 + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  return c;
}

function toTexture(canvas: HTMLCanvasElement, isColor: boolean, anisotropy: number): THREE.CanvasTexture {
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = isColor ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.anisotropy = Math.min(16, anisotropy);
  tex.generateMipmaps = true;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.magFilter = THREE.LinearFilter;
  tex.needsUpdate = true;
  return tex;
}

const clamp255 = (v: number) => Math.max(0, Math.min(255, Math.round(v)));

/**
 * Generates all procedural roof textures in non-blocking idle slices.
 * Resolution is capped at 1024 on desktop and 512 on mobile.
 */
export async function generateProceduralTextures(
  size: 1024 | 512,
  maxAnisotropy = 8
): Promise<ProceduralTextureSet> {
  const rng = createSeededRng(20261018);
  const allTextures: THREE.CanvasTexture[] = [];
  const reg = (t: THREE.CanvasTexture) => {
    allTextures.push(t);
    return t;
  };
  const S = size;

  /* ── 1. ASPHALT SHINGLE GRANULES (Albedo + Normal + Roughness) ────────────
     Texture spans 0.5 m. Ceramic-coated mineral granules in a charcoal blend. */
  {
    const [colC, colCtx] = makeCanvas(S);
    const colImg = colCtx.createImageData(S, S);
    const height = new Float32Array(S * S);
    const rough = new Float32Array(S * S);
    const blotch = createFbm(rng, 6, 4);
    const granPx = S >= 1024 ? 2 : 1;
    const cells = S / granPx;
    // Per-granule values (granules ~1mm)
    for (let gy = 0; gy < cells; gy++) {
      for (let gx = 0; gx < cells; gx++) {
        const pick = rng();
        let r: number, g: number, b: number;
        if (pick < 0.34) {
          r = 36; g = 38; b = 41; // charcoal
        } else if (pick < 0.62) {
          r = 48; g = 50; b = 54; // slate
        } else if (pick < 0.8) {
          r = 25; g = 26; b = 28; // onyx
        } else if (pick < 0.93) {
          r = 66; g = 68; b = 72; // weathered gray
        } else if (pick < 0.975) {
          r = 74; g = 62; b = 52; // warm mineral
        } else {
          r = 108; g = 110; b = 114; // bright quartz
        }
        const n = rng();
        const bl = blotch(gx / cells, gy / cells);
        const tone = 0.82 + bl * 0.36 + (n - 0.5) * 0.16;
        const hv = 0.35 + n * 0.6;
        const rv = 0.78 + (1 - n) * 0.18;
        for (let dy = 0; dy < granPx; dy++) {
          for (let dx = 0; dx < granPx; dx++) {
            const px = gx * granPx + dx;
            const py = gy * granPx + dy;
            const i = py * S + px;
            const edge = granPx > 1 && (dx === granPx - 1 || dy === granPx - 1) ? 0.86 : 1;
            colImg.data[i * 4] = clamp255(r * tone * edge);
            colImg.data[i * 4 + 1] = clamp255(g * tone * edge);
            colImg.data[i * 4 + 2] = clamp255(b * tone * edge);
            colImg.data[i * 4 + 3] = 255;
            height[i] = hv * edge;
            rough[i] = pick > 0.975 ? 0.55 : rv;
          }
        }
      }
    }
    colCtx.putImageData(colImg, 0, 0);
    var shingleColor = reg(toTexture(colC, true, maxAnisotropy));
    var shingleNormal = reg(toTexture(heightToNormalCanvas(height, S, S, 2.6), false, maxAnisotropy));
    var shingleRoughness = reg(toTexture(grayCanvas(rough, S, S), false, maxAnisotropy));
  }
  await yieldToIdle();

  /* ── 2. SYNTHETIC UNDERLAYMENT (woven polypropylene + printed lap lines) ──
     Texture spans 1.0 m. */
  {
    const [colC, ctx] = makeCanvas(S);
    const img = ctx.createImageData(S, S);
    const height = new Float32Array(S * S);
    const tape = Math.max(4, Math.round(S / 170));
    const mott = createFbm(rng, 4, 4);
    for (let y = 0; y < S; y++) {
      for (let x = 0; x < S; x++) {
        const i = y * S + x;
        const warp = (Math.floor(x / tape) + Math.floor(y / tape)) % 2 === 0;
        const local = warp ? (x % tape) / tape : (y % tape) / tape;
        const weave = Math.sin(local * Math.PI);
        const m = mott(x / S, y / S);
        const base = 0.92 + m * 0.07 + (warp ? 0.02 : -0.02) + weave * 0.03;
        img.data[i * 4] = clamp255(236 * base);
        img.data[i * 4 + 1] = clamp255(236 * base);
        img.data[i * 4 + 2] = clamp255(240 * base);
        img.data[i * 4 + 3] = 255;
        height[i] = 0.5 + weave * 0.35 * (warp ? 1 : 0.8);
      }
    }
    ctx.putImageData(img, 0, 0);

    // Printed magenta lap guide lines (4" lap) + dashed nailing lines
    const MAG = 'rgba(206, 32, 96, 0.9)';
    ctx.strokeStyle = MAG;
    ctx.lineWidth = Math.max(2, S / 300);
    [0.085, 0.915].forEach((t) => {
      ctx.beginPath();
      ctx.moveTo(0, S * t);
      ctx.lineTo(S, S * t);
      ctx.stroke();
    });
    ctx.save();
    ctx.setLineDash([S * 0.018, S * 0.012]);
    ctx.lineWidth = Math.max(1.5, S / 512);
    [0.5].forEach((t) => {
      ctx.beginPath();
      ctx.moveTo(0, S * t);
      ctx.lineTo(S, S * t);
      ctx.stroke();
    });
    ctx.restore();
    // Fastener target marks
    ctx.fillStyle = MAG;
    for (let gy = 0; gy < 2; gy++) {
      for (let gx = 0; gx < 8; gx++) {
        const cx = (gx + 0.5) * (S / 8);
        const cy = S * (0.16 + gy * 0.68);
        ctx.fillRect(cx - S * 0.006, cy - S * 0.0015, S * 0.012, S * 0.003);
        ctx.fillRect(cx - S * 0.0015, cy - S * 0.006, S * 0.003, S * 0.012);
      }
    }
    // Brand print (two staggered rows)
    for (let row = 0; row < 2; row++) {
      const y = S * (0.34 + row * 0.34);
      const shift = row % 2 === 0 ? 0 : S * 0.5;
      for (const x0 of [S * 0.06 + shift, S * 0.06 + shift - S]) {
        ctx.fillStyle = MAG;
        ctx.font = `italic 800 ${Math.round(S * 0.05)}px Arial, Helvetica, sans-serif`;
        ctx.fillText('Rise Up', x0, y);
        ctx.font = `700 ${Math.round(S * 0.018)}px Arial, Helvetica, sans-serif`;
        ctx.fillStyle = 'rgba(60, 60, 70, 0.75)';
        ctx.fillText('PRO-GUARD™ SYNTHETIC UNDERLAYMENT', x0, y + S * 0.032);
        ctx.fillStyle = MAG;
        ctx.fillRect(x0 + S * 0.33, y - S * 0.035, S * 0.05, S * 0.04);
      }
    }
    var underlaymentColor = reg(toTexture(colC, true, maxAnisotropy));
    var underlaymentNormal = reg(toTexture(heightToNormalCanvas(height, S, S, 1.6), false, maxAnisotropy));
  }
  await yieldToIdle();

  /* ── 3. ICE & WATER SHIELD (embossed rubberized membrane, navy) ───────────
     Texture spans 1.0 m. */
  {
    const IW = 512;
    const [colC, ctx] = makeCanvas(IW);
    const img = ctx.createImageData(IW, IW);
    const height = new Float32Array(IW * IW);
    const rough = new Float32Array(IW * IW);
    const mott = createFbm(rng, 4, 4);
    for (let y = 0; y < IW; y++) {
      for (let x = 0; x < IW; x++) {
        const i = y * IW + x;
        const n = rng();
        // embossed micro-diamond pattern typical of slip-resistant membranes
        const d = Math.abs(((x + y) % 10) - 5) + Math.abs(((x - y + 1000) % 10) - 5);
        const emb = d < 3 ? 1 : 0;
        const m = mott(x / IW, y / IW);
        const tone = 0.9 + m * 0.18 + (n - 0.5) * 0.12 + emb * 0.06;
        img.data[i * 4] = clamp255(30 * tone);
        img.data[i * 4 + 1] = clamp255(31 * tone);
        img.data[i * 4 + 2] = clamp255(35 * tone);
        img.data[i * 4 + 3] = 255;
        height[i] = 0.45 + emb * 0.3 + n * 0.2;
        rough[i] = 0.5 + n * 0.14 - emb * 0.06;
      }
    }
    ctx.putImageData(img, 0, 0);
    const MAG = 'rgba(214, 40, 104, 0.92)';
    ctx.strokeStyle = MAG;
    ctx.lineWidth = 2.5;
    [0.07, 0.93].forEach((t) => {
      ctx.beginPath();
      ctx.moveTo(0, IW * t);
      ctx.lineTo(IW, IW * t);
      ctx.stroke();
    });
    for (let row = 0; row < 2; row++) {
      const y = IW * (0.36 + row * 0.36);
      const shift = row % 2 === 0 ? 0 : IW * 0.5;
      for (const x0 of [IW * 0.05 + shift, IW * 0.05 + shift - IW]) {
        ctx.fillStyle = MAG;
        ctx.font = `italic 800 ${Math.round(IW * 0.048)}px Arial, Helvetica, sans-serif`;
        ctx.fillText('Rise Up', x0, y);
        ctx.fillStyle = 'rgba(220, 220, 228, 0.6)';
        ctx.font = `700 ${Math.round(IW * 0.018)}px Arial, Helvetica, sans-serif`;
        ctx.fillText('ICE & WATER BARRIER · SELF-ADHERED', x0, y + IW * 0.03);
      }
    }
    var iceWaterColor = reg(toTexture(colC, true, maxAnisotropy));
    var iceWaterNormal = reg(toTexture(heightToNormalCanvas(height, IW, IW, 2.0), false, maxAnisotropy));
    var iceWaterRoughness = reg(toTexture(grayCanvas(rough, IW, IW), false, maxAnisotropy));
  }
  await yieldToIdle();

  /* ── 4. CDX PLYWOOD FACE (rotary-cut veneer, knots, patches, APA stamp) ──
     Texture spans 1.22 m. Grain runs along U (texture X). */
  {
    const [colC, ctx] = makeCanvas(S);
    const img = ctx.createImageData(S, S);
    const height = new Float32Array(S * S);
    const rough = new Float32Array(S * S);
    const warpN = createFbm(rng, 3, 4);
    const fine = createFbm(rng, 16, 3);
    const blot = createFbm(rng, 5, 3);
    for (let y = 0; y < S; y++) {
      for (let x = 0; x < S; x++) {
        const u = x / S;
        const v = y / S;
        const w = warpN(u, v);
        // Cathedral figure: stretched rings along U, warped by low-freq noise
        const rings = v * 26 + w * 7.5 + Math.sin(u * Math.PI * 2) * 0.6;
        const fr = rings - Math.floor(rings);
        const late = Math.pow(Math.max(0, 1 - Math.abs(fr - 0.5) * 2), 5);
        const streak = fine(u * 0.25, v * 4) * 0.5;
        const b = blot(u, v);
        const tone = 0.93 + b * 0.12 - late * 0.2 - streak * 0.08;
        const i = y * S + x;
        img.data[i * 4] = clamp255(222 * tone);
        img.data[i * 4 + 1] = clamp255(180 * tone);
        img.data[i * 4 + 2] = clamp255(124 * tone);
        img.data[i * 4 + 3] = 255;
        height[i] = 0.5 - late * 0.3 + streak * 0.2;
        rough[i] = 0.72 + late * 0.1;
      }
    }
    ctx.putImageData(img, 0, 0);

    const knots = [
      { x: 0.22, y: 0.3, r: 0.018 },
      { x: 0.71, y: 0.66, r: 0.014 },
      { x: 0.53, y: 0.14, r: 0.011 },
      { x: 0.86, y: 0.9, r: 0.016 },
    ];
    knots.forEach((k) => {
      const g = ctx.createRadialGradient(S * k.x, S * k.y, 1, S * k.x, S * k.y, S * k.r * 2.2);
      g.addColorStop(0, 'rgba(70, 42, 20, 0.95)');
      g.addColorStop(0.45, 'rgba(118, 76, 38, 0.8)');
      g.addColorStop(1, 'rgba(190, 150, 100, 0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.ellipse(S * k.x, S * k.y, S * k.r * 2.2, S * k.r * 1.2, 0, 0, Math.PI * 2);
      ctx.fill();
    });
    [
      { x: 0.36, y: 0.76, w: 0.05, h: 0.022 },
      { x: 0.82, y: 0.28, w: 0.045, h: 0.019 },
    ].forEach((p) => {
      ctx.save();
      ctx.translate(S * p.x, S * p.y);
      ctx.fillStyle = 'rgba(214, 176, 120, 0.95)';
      ctx.strokeStyle = 'rgba(110, 76, 40, 0.6)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(-S * p.w, 0);
      ctx.quadraticCurveTo(0, -S * p.h, S * p.w, 0);
      ctx.quadraticCurveTo(0, S * p.h, -S * p.w, 0);
      ctx.fill();
      ctx.stroke();
      ctx.restore();
    });
    // APA grade stamp
    ctx.save();
    ctx.translate(S * 0.4, S * 0.46);
    ctx.rotate(-0.015);
    ctx.strokeStyle = 'rgba(40, 32, 26, 0.55)';
    ctx.fillStyle = 'rgba(40, 32, 26, 0.55)';
    ctx.lineWidth = Math.max(2, S / 400);
    const sw = S * 0.2;
    const sh = S * 0.1;
    ctx.strokeRect(0, 0, sw, sh);
    ctx.font = `800 ${Math.round(S * 0.02)}px Arial, Helvetica, sans-serif`;
    ctx.fillText('APA RATED SHEATHING', sw * 0.06, sh * 0.32);
    ctx.font = `700 ${Math.round(S * 0.017)}px Arial, Helvetica, sans-serif`;
    ctx.fillText('48/24 · 19/32 INCH', sw * 0.06, sh * 0.6);
    ctx.fillText('EXPOSURE 1 · PS 1-19', sw * 0.06, sh * 0.86);
    ctx.restore();

    var plywoodColor = reg(toTexture(colC, true, maxAnisotropy));
    var plywoodNormal = reg(toTexture(heightToNormalCanvas(height, S, S, 1.6), false, maxAnisotropy));
    var plywoodRoughness = reg(toTexture(grayCanvas(rough, S, S), false, maxAnisotropy));
  }
  await yieldToIdle();

  /* ── 5. PLYWOOD EDGE (5-ply cross-laminated veneers) ─────────────────────
     U = meters along the edge, V = 0..1 across sheet thickness. */
  {
    const W = 512;
    const H = 64;
    const [c, ctx] = makeCanvas(W, H);
    const img = ctx.createImageData(W, H);
    const plies = 5;
    for (let y = 0; y < H; y++) {
      const t = (y / H) * plies;
      const ply = Math.floor(t);
      const f = t - ply;
      const glue = f < 0.07 || f > 0.93;
      const cross = ply % 2 === 1;
      for (let x = 0; x < W; x++) {
        const n = rng();
        let tone = cross ? 0.8 + n * 0.1 + (x % 3 === 0 ? -0.06 : 0) : 0.96 + n * 0.08;
        if (glue) tone = 0.55;
        const i = y * W + x;
        img.data[i * 4] = clamp255(214 * tone);
        img.data[i * 4 + 1] = clamp255(170 * tone);
        img.data[i * 4 + 2] = clamp255(112 * tone);
        img.data[i * 4 + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
    var plywoodEdge = reg(toTexture(c, true, maxAnisotropy));
  }
  await yieldToIdle();

  /* ── 6. KILN-DRIED SPF LUMBER (straight grain along V, knots, mill stamp) ─
     Texture spans 0.25 m across × 1.0 m along the grain. */
  {
    const W = 256;
    const H = 1024;
    const [colC, ctx] = makeCanvas(W, H);
    const img = ctx.createImageData(W, H);
    const height = new Float32Array(W * H);
    const rough = new Float32Array(W * H);
    const warpN = createFbm(rng, 4, 4);
    const fine = createFbm(rng, 32, 2);
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const u = x / W;
        const v = y / H;
        const w = warpN(u * 0.5, v);
        const g = u * 9 + w * 2.6;
        const fr = g - Math.floor(g);
        const late = Math.pow(Math.max(0, 1 - Math.abs(fr - 0.5) * 2), 6);
        const fib = fine(u, v * 0.2);
        const tone = 0.96 - late * 0.2 + (fib - 0.5) * 0.08;
        const i = y * W + x;
        img.data[i * 4] = clamp255(232 * tone);
        img.data[i * 4 + 1] = clamp255(196 * tone);
        img.data[i * 4 + 2] = clamp255(140 * tone);
        img.data[i * 4 + 3] = 255;
        height[i] = 0.5 - late * 0.35 + fib * 0.1;
        rough[i] = 0.68 + late * 0.12;
      }
    }
    ctx.putImageData(img, 0, 0);
    [
      { x: 0.35, y: 0.22, r: 0.07 },
      { x: 0.7, y: 0.71, r: 0.05 },
    ].forEach((k) => {
      const g = ctx.createRadialGradient(W * k.x, H * k.y, 1, W * k.x, H * k.y, W * k.r * 1.6);
      g.addColorStop(0, 'rgba(92, 54, 24, 0.95)');
      g.addColorStop(0.5, 'rgba(140, 92, 48, 0.7)');
      g.addColorStop(1, 'rgba(220, 180, 120, 0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.ellipse(W * k.x, H * k.y, W * k.r * 1.2, W * k.r * 2.2, 0, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.save();
    ctx.translate(W * 0.18, H * 0.47);
    ctx.rotate(Math.PI / 2);
    ctx.fillStyle = 'rgba(36, 52, 110, 0.5)';
    ctx.font = `800 ${Math.round(W * 0.11)}px Arial, Helvetica, sans-serif`;
    ctx.fillText('SPF  No.2  KD-HT', 0, 0);
    ctx.restore();
    var lumberColor = reg(toTexture(colC, true, maxAnisotropy));
    var lumberNormal = reg(toTexture(heightToNormalCanvas(height, W, H, 2.2), false, maxAnisotropy));
    var lumberRoughness = reg(toTexture(grayCanvas(rough, W, H), false, maxAnisotropy));
  }
  await yieldToIdle();

  /* ── 7. PINK FIBERGLASS INSULATION (lofted fibers + clumps) ──────────────
     Texture spans 0.6 m. */
  {
    const IN = 512;
    const [colC, ctx] = makeCanvas(IN);
    const img = ctx.createImageData(IN, IN);
    const clump = createFbm(rng, 6, 5);
    for (let y = 0; y < IN; y++) {
      for (let x = 0; x < IN; x++) {
        const c = clump(x / IN, y / IN);
        const n = rng();
        const tone = 0.82 + c * 0.3 + (n - 0.5) * 0.1;
        const i = y * IN + x;
        img.data[i * 4] = clamp255(246 * tone);
        img.data[i * 4 + 1] = clamp255(150 * tone);
        img.data[i * 4 + 2] = clamp255(178 * tone);
        img.data[i * 4 + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
    const [hC, hCtx] = makeCanvas(IN);
    const hImg = hCtx.createImageData(IN, IN);
    for (let y = 0; y < IN; y++) {
      for (let x = 0; x < IN; x++) {
        const v = clamp255(clump(x / IN, y / IN) * 255);
        const i = (y * IN + x) * 4;
        hImg.data[i] = hImg.data[i + 1] = hImg.data[i + 2] = v;
        hImg.data[i + 3] = 255;
      }
    }
    hCtx.putImageData(hImg, 0, 0);
    // Tangled spun-glass fibers (drawn with wrap-around for tiling)
    for (let s = 0; s < 2600; s++) {
      const x0 = rng() * IN;
      const y0 = rng() * IN;
      const ang = rng() * Math.PI * 2;
      const len = 10 + rng() * 40;
      const x1 = x0 + Math.cos(ang) * len;
      const y1 = y0 + Math.sin(ang) * len;
      const cx = (x0 + x1) * 0.5 + (rng() - 0.5) * 18;
      const cy = (y0 + y1) * 0.5 + (rng() - 0.5) * 18;
      const light = rng() > 0.45;
      for (const [ox, oy] of [
        [0, 0],
        [-IN, 0],
        [0, -IN],
        [-IN, -IN],
      ]) {
        ctx.strokeStyle = light ? 'rgba(255, 222, 234, 0.32)' : 'rgba(186, 74, 118, 0.26)';
        ctx.lineWidth = 0.8 + rng() * 0.8;
        ctx.beginPath();
        ctx.moveTo(x0 + ox, y0 + oy);
        ctx.quadraticCurveTo(cx + ox, cy + oy, x1 + ox, y1 + oy);
        ctx.stroke();
        hCtx.strokeStyle = light ? 'rgba(255,255,255,0.35)' : 'rgba(0,0,0,0.3)';
        hCtx.lineWidth = 1.2;
        hCtx.beginPath();
        hCtx.moveTo(x0 + ox, y0 + oy);
        hCtx.quadraticCurveTo(cx + ox, cy + oy, x1 + ox, y1 + oy);
        hCtx.stroke();
      }
    }
    var insulationColor = reg(toTexture(colC, true, maxAnisotropy));
    var insulationNormal = reg(
      toTexture(heightToNormalCanvas(canvasToHeight(hCtx, IN, IN), IN, IN, 3.4), false, maxAnisotropy)
    );
  }
  await yieldToIdle();

  /* ── 8. GALVANIZED TRUSS PLATES / FLASHING (spangle + punched teeth) ─────
     Texture spans 0.2 m. */
  {
    const M = 256;
    const [colC, ctx] = makeCanvas(M);
    const img = ctx.createImageData(M, M);
    const height = new Float32Array(M * M);
    const spangle = createTileNoise(rng, 10);
    const sp2 = createTileNoise(rng, 23);
    for (let y = 0; y < M; y++) {
      for (let x = 0; x < M; x++) {
        const s = Math.floor(spangle(x / M, y / M) * 5) / 5;
        const s2 = sp2(x / M, y / M);
        const tooth = x % 16 >= 6 && x % 16 <= 9 && y % 22 >= 4 && y % 22 <= 15;
        const tone = tooth ? 0.42 : 0.86 + s * 0.12 + s2 * 0.05;
        const i = y * M + x;
        img.data[i * 4] = clamp255(182 * tone);
        img.data[i * 4 + 1] = clamp255(188 * tone);
        img.data[i * 4 + 2] = clamp255(194 * tone);
        img.data[i * 4 + 3] = 255;
        height[i] = tooth ? 0.1 : 0.6;
      }
    }
    ctx.putImageData(img, 0, 0);
    var metalColor = reg(toTexture(colC, true, maxAnisotropy));
    var metalNormal = reg(toTexture(heightToNormalCanvas(height, M, M, 2.0), false, maxAnisotropy));
  }
  await yieldToIdle();

  /* ── 9. PERFORATED VINYL SOFFIT (vent holes + V-grooves) ──────────────────
     Texture spans 0.4 m. */
  {
    const P = 512;
    const [colC, ctx] = makeCanvas(P);
    const img = ctx.createImageData(P, P);
    const height = new Float32Array(P * P);
    const panel = P / 2;
    for (let y = 0; y < P; y++) {
      for (let x = 0; x < P; x++) {
        const py = y % panel;
        const groove = py < 4 || (py > panel / 2 - 2 && py < panel / 2 + 2);
        const hx = x % 12;
        const hy = py % 12;
        const hole =
          py > 14 && py < panel - 10 && !groove && (hx - 6) * (hx - 6) + (hy - 6) * (hy - 6) < 7;
        const tone = hole ? 0.16 : groove ? 0.78 : 0.95 + (rng() - 0.5) * 0.03;
        const i = y * P + x;
        img.data[i * 4] = clamp255(242 * tone);
        img.data[i * 4 + 1] = clamp255(242 * tone);
        img.data[i * 4 + 2] = clamp255(238 * tone);
        img.data[i * 4 + 3] = 255;
        height[i] = hole ? 0 : groove ? 0.3 : 0.7;
      }
    }
    ctx.putImageData(img, 0, 0);
    var soffitColor = reg(toTexture(colC, true, maxAnisotropy));
    var soffitNormal = reg(toTexture(heightToNormalCanvas(height, P, P, 2.0), false, maxAnisotropy));
  }
  await yieldToIdle();

  /* ── 10. LOUVERED EAVE INTAKE VENT (rows of slots in light-gray polymer) ───
     U spans 0.25 m along the eave, V spans the full strip width (0..1). */
  {
    const W = 256;
    const H = 256;
    const [colC, ctx] = makeCanvas(W, H);
    const img = ctx.createImageData(W, H);
    const height = new Float32Array(W * H);
    const rows = [0.2, 0.36, 0.52, 0.68];
    for (let y = 0; y < H; y++) {
      const v = y / H;
      for (let x = 0; x < W; x++) {
        const cx = x % 16;
        let slot = false;
        for (const r of rows) {
          if (Math.abs(v - r) < 0.035 && cx >= 2 && cx <= 13) slot = true;
        }
        const rib = Math.abs(v - 0.86) < 0.012 || Math.abs(v - 0.08) < 0.012;
        const tone = slot ? 0.12 : rib ? 0.78 : 0.93 + (rng() - 0.5) * 0.03;
        const i = y * W + x;
        img.data[i * 4] = clamp255(226 * tone);
        img.data[i * 4 + 1] = clamp255(229 * tone);
        img.data[i * 4 + 2] = clamp255(232 * tone);
        img.data[i * 4 + 3] = 255;
        height[i] = slot ? 0 : rib ? 0.85 : 0.6;
      }
    }
    ctx.putImageData(img, 0, 0);
    var ventColor = reg(toTexture(colC, true, maxAnisotropy));
    var ventNormal = reg(toTexture(heightToNormalCanvas(height, W, H, 2.4), false, maxAnisotropy));
  }

  return {
    shingleColor,
    shingleNormal,
    shingleRoughness,
    underlaymentColor,
    underlaymentNormal,
    iceWaterColor,
    iceWaterNormal,
    iceWaterRoughness,
    plywoodColor,
    plywoodNormal,
    plywoodRoughness,
    plywoodEdge,
    lumberColor,
    lumberNormal,
    lumberRoughness,
    insulationColor,
    insulationNormal,
    metalColor,
    metalNormal,
    soffitColor,
    soffitNormal,
    ventColor,
    ventNormal,
    dispose() {
      allTextures.forEach((t) => t.dispose());
    },
  };
}
